			CreateAllQueries(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllScreens(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllTabs(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllEventTypes(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllClosedTables(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllFeatures(contextTenant);
			CreateAdditionalTextCodes(contextTenant);
		    this.ObjectContext.SaveChanges();

			CreateAllMenuButtons(contextTenant);
		    this.ObjectContext.SaveChanges();

        }

		public void LoadObjectTablesMetadata(IAmitalCloudContext context, bool runPostDeleteProcedure,int contextTenant=0)
        {
		    ObjectContext = context;
            TextCodeRepository = new Repository<TextCode>(context);
            ObjectTableRepository = new Repository<ObjectTable>(context);
            ObjectFieldsRepository = new Repository<ObjectField>(context);
            queriesRepository = new Repository<Query>(context);
            queryColumnsRepository = new Repository<QueryColumn>(context);
            queryGroupRepository = new Repository<QueryGroup>(context);
            advancedQueryFiltersRepository = new Repository<AdvancedQueryFilter>(context);
            screensRepository = new Repository<Screen>(context);
            screenFieldsRepository = new Repository<ScreenField>(context);
            objectTableTabsRepository = new Repository<ObjectTableTab>(context);
            EventTypeRepository = new Repository<EventType>(context);
            menuButtonRepository = new Repository<MenuButton>(context);
            menuButtonGroupRepository = new Repository<MenuButtonGroup>(context);
            FeaturesRepository = new Repository<Feature>(context);
            EntityStatusRepository = new Repository<EntityStatus>(context);


             ObjectTables = ObjectTableRepository.GetAll(0).ToDictionary(d => d.Name, a => a);
            ObjectTable generalTable = ObjectTables["General"];
            TextCodes = TextCodeRepository.GetAll(0).Where(t => t.ObjectTableId == generalTable.Id).ToDictionary(d => d.Code + d.Tenant.ToString() + d.ObjectTableId, a => a, StringComparer.OrdinalIgnoreCase);
			TenantFeatures = FeaturesRepository.GetAll(0).Where(t => t.ObjectTableId == generalTable.Id).ToDictionary(d => d.Code + d.ObjectTableId, a => a);
			ObjectFields = new Dictionary<string, ObjectField>();
			Queries = new Dictionary<string, Query>();
			QueryColumns = new Dictionary<string, QueryColumn>();
			tenantAdvancedFilters = new Dictionary<string, AdvancedQueryFilter>();
			tenantScreens = new Dictionary<string, Screen>();
			tenantScreenFields = new Dictionary<string, ScreenField>();
			TenantObjectTableTabs = new Dictionary<string, ObjectTableTab>();
			tenantEventTypes = EventTypeRepository.GetAll(0).ToDictionary(d => d.Code + d.ObjectTableId, a => a);
			tenantMenuButtons = new Dictionary<string, MenuButton>();
			tenantMenuButtonGroups = menuButtonGroupRepository.GetAll(0).ToDictionary(d => d.Name, a => a);
			AllEntityStatuses = EntityStatusRepository.GetAll(0).ToList();
			tenantQueryGroups = queryGroupRepository.GetQueryable().ToDictionary(d => d.Code, a => a);	


			 MetadataUpdateUtility.RunPreDeleteProcedure(contextTenant);

			 CreateAllObjectTablesMetadata(contextTenant);
			 
 
			 this.ObjectContext.SaveChanges();
			 if(runPostDeleteProcedure)
			 {
				MetadataUpdateUtility.RunPostDeleteProcedure(contextTenant);
			 }
			
        }

